COPY ref.enrollment_status (status_code, name, is_billable, closes_receivable) FROM stdin;
WAITLISTED	Waiting for a class	t	f
REGISTERED	Registered	t	f
ACTIVE	Active student	t	f
COMPLETED	Completed the course	t	f
DROPPED	Dropped out mid-course	f	t
DEFERRED	Deferred (on hold)	f	f
CANCELLED	Cancelled before start	f	t
\.
COPY ref.payment_plan (plan_code, name, materials_fee_applies, description) FROM stdin;
FULL	Pay in full	f	Whole balance due at class start
P50_30_20	50-30-20 instalments	t	50% at start, 30% after one month, 20% after two months; materials fee added
MONTHLY_3	Monthly - 3 instalments	t	Balance split over three monthly instalments; materials fee added
MONTHLY_5	Monthly - 5 instalments	t	Balance split over five monthly instalments; materials fee added
\.
